#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    int k;
    cin >> s >> k;
    string stk;
    for (char c : s) {
        while (!stk.empty() && k > 0 && stk.back() > c) {
            stk.pop_back();
            k--;
        }
        stk.push_back(c);
    }
    while (k > 0) {
        stk.pop_back();
        k--;
    }
    int start = 0;
    while (start < (int)stk.size() - 1 && stk[start] == '0') start++;
