#include <iostream>
#include <algorithm>
using namespace std;

struct Edge {
    int u, v, w;
};

int parent[10001];

int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]);
    return parent[x];
}

void unite(int a, int b) {
    parent[find(a)] = find(b);
}

int main() {
    int n, m;
    cin >> n >> m;
    Edge edges[100000];
    for (int i = 0; i < m; i++)
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    sort(edges, edges + m, [](const Edge& a, const Edge& b) {
        return a.w < b.w;
    });
    for (int i = 1; i <= n; i++) parent[i] = i;
    long long total = 0;
    int cnt = 0;
    for (int i = 0; i < m && cnt < n - 1; i++) {
        if (find(edges[i].u) != find(edges[i].v)) {
            unite(edges[i].u, edges[i].v);
            total += edges[i].w;
            cnt++;
        }
    }
    cout << total << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int n;
vector<int> children[10001];
int state[10001];

int dfs(int u) {
    if (children[u].empty()) return 0;
    int res = 0;
    for (int v : children[u]) res += dfs(v);
    bool hasUncovered = false;
    for (int v : children[u]) {
        if (state[v] == 0) hasUncovered = true;
    }
    if (hasUncovered) {
        state[u] = 2;
        for (int v : children[u]) state[v] = max(state[v], 1);
        res++;
    }
    return res;
}

int main() {
    cin >> n;
    for (int i = 2; i <= n; i++) {
        int p;
        cin >> p;
        children[p].push_back(i);
    }
    int ans = dfs(1);
    if (state[1] == 0) ans++;
    cout << ans << endl;
    return 0;
}

