#include <iostream>
#include <string>
#include <queue>
using namespace std;

struct Node {
    char ch;
    int cnt;
    bool operator<(const Node& o) const { return cnt < o.cnt; }
};

int main() {
    string s;
    cin >> s;
    int freq[26] = {};
    for (char c : s) freq[c - 'a']++;
    priority_queue<Node> pq;
    for (int i = 0; i < 26; i++) {
        if (freq[i] > 0) pq.push({(char)('a' + i), freq[i]});
    }
    string result;
    Node prev = {0, 0};
    while (!pq.empty()) {
        Node cur = pq.top(); pq.pop();
        result += cur.ch;
        cur.cnt--;
        if (prev.cnt > 0) pq.push(prev);
        prev = cur;
    }
    bool valid = true;
    for (int i = 1; i < (int)result.size(); i++) {
        if (result[i] == result[i-1]) valid = false;
    }
    if (valid) cout << result << endl;
    else cout << "" << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
#include <queue>
using namespace std;

int main() {
    int n;
    cin >> n;
    pair<int,int> courses[100000];
    for (int i = 0; i < n; i++) cin >> courses[i].first >> courses[i].second;
    sort(courses, courses + n, [](const auto& a, const auto& b) {
        return a.second < b.second;
    });
    priority_queue<int> selected;
    long long totalTime = 0;
    for (int i = 0; i < n; i++) {
        int duration = courses[i].first;
        int deadline = courses[i].second;
        totalTime += duration;
        selected.push(duration);
        if (totalTime > deadline) {
            totalTime -= selected.top();
            selected.pop();
        }
    }
    cout << selected.size() << endl;
    return 0;
}

