#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int W = 10;
    int w[] = {7, 5, 5};
    int v[] = {7, 5, 5};
    int n = 3;

    double ratio[3];
    int idx[3] = {0, 1, 2};
    for (int i = 0; i < n; i++) ratio[i] = (double)v[i] / w[i];
    sort(idx, idx + n, [&](int a, int b) { return ratio[a] > ratio[b]; });

    int greedyVal = 0, greedyW = 0;
    for (int i = 0; i < n; i++) {
        if (greedyW + w[idx[i]] <= W) {
            greedyW += w[idx[i]];
            greedyVal += v[idx[i]];
        }
    }

    int dp[11] = {};
    for (int i = 0; i < n; i++)
        for (int j = W; j >= w[i]; j--)
            dp[j] = max(dp[j], dp[j - w[i]] + v[i]);

    cout << "greedy=" << greedyVal << endl;
    cout << "dp=" << dp[W] << endl;
    return 0;
}
